import json
import textwrap


class HTTPException(Exception):
    def __init__(self, status_code, detail=None):
        super().__init__(status_code)
        self.status_code = status_code


class Router:
    def get(self, path):
        return lambda fn: fn


class User:
    def __init__(self, customer_id):
        self.customer_id = customer_id


def current_user():
    raise HTTPException(401)


INVOICES = [
    {"id": "INV-1701", "customer_id": 42, "amount": "AUD 410.00", "status": "paid"},
    {"id": "INV-1702", "customer_id": 42, "amount": "AUD 96.20", "status": "due"},
    {"id": "INV-1703", "customer_id": 17, "amount": "AUD 1,240.00", "status": "paid"},
    {"id": "INV-1711", "customer_id": 17, "amount": "AUD 385.50", "status": "due"},
    {"id": "INV-1729", "customer_id": 17, "amount": "AUD 2,016.00", "status": "due"},
]
OWNER = {r["id"]: r["customer_id"] for r in INVOICES}


class DB:
    """Runs the one query shape the code uses: the selected columns, filtered by customer_id when the query asks."""

    def execute(self, sql, params):
        cols = [c.strip() for c in sql.split("SELECT", 1)[1].split("FROM", 1)[0].split(",")]
        rows = [r for r in INVOICES if "customer_id = :cid" not in sql or r["customer_id"] == params["cid"]]
        return [{c: r[c] for c in cols} for r in rows]


ns = {"router": Router(), "Depends": lambda dep: dep, "User": User, "current_user": current_user, "db": DB(),
      "HTTPException": HTTPException}
exec(textwrap.dedent(open("subject.py").read()), ns)

# Logged in as customer 42, asking for customer 17.
try:
    out = ns["list_invoices"](customer_id=17, user=User(42))
except HTTPException as e:
    names = {401: "401 Unauthorized", 403: "403 Forbidden"}
    print(json.dumps({"option": str(e.status_code), "status": names.get(e.status_code, str(e.status_code)), "rows": []}))
else:
    owners = {OWNER[r["id"]] for r in out}
    option = "empty" if not out else "others" if owners - {42} else "own"
    rows = [[r["id"], r["amount"], r["status"]] for r in out]
    print(json.dumps({"option": option, "status": "200 OK", "result": f"{len(rows)} invoices", "rows": rows}))

