import json
import textwrap


class HTTPException(Exception):
    def __init__(self, status_code, detail=None):
        super().__init__(status_code)
        self.status_code = status_code


class Router:
    def get(self, path):
        return lambda fn: fn


class User:
    def __init__(self, customer_id):
        self.customer_id = customer_id


def current_user():
    raise HTTPException(401)


class Invoice:
    def __init__(self, id, customer_id, total):
        self.id, self.customer_id, self.total = id, customer_id, total


ROWS = {1701: Invoice(1701, 42, "AUD 410.00"), 1703: Invoice(1703, 17, "AUD 1,240.00")}


class DB:
    def get(self, model, key):
        return ROWS.get(key) if model is Invoice else None


def render_pdf(inv):
    return b"%PDF-1.7 invoice " + str(inv.id).encode()


ns = {"router": Router(), "Depends": lambda dep: dep, "User": User, "current_user": current_user, "db": DB(),
      "Invoice": Invoice, "HTTPException": HTTPException, "render_pdf": render_pdf}
exec(textwrap.dedent(open("subject.py").read()), ns)

# Logged in as customer 42, asking for invoice 1703, which belongs to customer 17.
try:
    out = ns["invoice_pdf"](invoice_id=1703, user=User(42))
except HTTPException as e:
    names = {403: "403 Forbidden", 404: "404 Not Found"}
    print(json.dumps({"option": str(e.status_code), "status": names.get(e.status_code, str(e.status_code)), "result": "No PDF.", "rows": []}))
except Exception as e:
    print(json.dumps({"option": "500", "status": "500 Server Error", "result": type(e).__name__, "rows": []}))
else:
    option = "pdf" if isinstance(out, bytes) and out.startswith(b"%PDF") else "other"
    print(json.dumps({"option": option, "status": "200 OK", "result": "A PDF", "rows": []}))
